const hook = $('Upload Webhook').first().json;
const body = hook.body || hook;
const driveFile = $input.first().json;

const now = new Date();
const pad = (n) => String(n).padStart(2, '0');
const contentId = 'W-' + String(now.getFullYear()).slice(-2) + pad(now.getMonth() + 1) + pad(now.getDate()) + '-' + pad(now.getHours()) + pad(now.getMinutes()) + pad(now.getSeconds());

const platforms = (Array.isArray(body.platforms) ? body.platforms.join(',') : (body.platforms || 'instagram,facebook,youtube')).toLowerCase();

let scheduled = now.toISOString();
if (body.scheduledDateTime && body.scheduledDateTime !== 'now') {
  const parsed = new Date(body.scheduledDateTime);
  if (!isNaN(parsed.getTime())) scheduled = parsed.toISOString();
}

return [{
  json: {
    'Content ID': contentId,
    'Title': body.title || 'Legal Awareness Post',
    'Caption': body.caption || '',
    'Platforms': platforms,
    'Scheduled DateTime': scheduled,
    'Status': body.status || 'Pending Review',
    'Retry Count': 0,
    'Posted At': '',
    'Error': '',
    'Public Media URL': body.publicMediaUrl || '',
    'Pinterest Board ID': body.pinterestBoardId || '',
    'Drive File ID': driveFile.id,
    'Instagram Status': '',
    'Facebook Status': '',
    'YouTube Status': '',
    'LinkedIn Status': '',
    'Pinterest Status': '',
    'Threads Status': '',
    driveFileUrl: driveFile.webViewLink || ('https://drive.google.com/file/d/' + driveFile.id + '/view')
  }
}];

// An empty sheet arrives as one empty item (alwaysOutputData), which this filter drops.
const rows = $input.all()
  .map((i) => i.json)
  .filter((r) => r['Content ID'] && String(r['Content ID']).trim() !== '');
return [{ json: { success: true, count: rows.length, posts: rows.reverse() } }];
